  "claim": {
    "component_id": "C058",
    "value": "Missing trace spans constitute unknown evidence rather than proof that the corresponding phase was fast.",
    "scope": "A distinction between missing measurement and evidence of short duration.",
    "provenance": {
      "refs": [
