      "support_status": "SUFFICIENT",
      "rationale": "The cited span directly supplies the distinction and its scope."
    }
  },
  "signal_basis": {
    "component_id": "C058_signal_basis",
    "value": "Trace coverage varies across worker versions, and phase durations are separated only where trace semantics permit; the comparison explicitly accommodates unknown evidence, including missing spans.",
    "scope": "Assessment of phase durations from the existing export traces.",
    "provenance": {
      "refs": [
