        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish variable coverage, the restriction on interpreting phase durations, and the treatment of missing measurements as unknown evidence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C058_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
